"""The AIOS Cedar schema (ADR-007), kept free of the ``cedarpy`` import so that ``aios specs`` and
``aios --version`` stay light."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Literal

from aios.core.policy import CONTROL_ACTIONS, WORKLOAD_ACTIONS, PolicyAction

SCHEMA_TEMPLATE = """\
// AIOS Cedar schema v0.2 (ADR-007, ADR-011). Compiled policies are validated against it.
// Generated by `aios specs export` from src/aios/security/cedar_schema.py. Do not edit.
entity Tenant;
entity Role in [Tenant];
entity App in [Tenant];
entity Agent in [App, Role, Tenant];
entity User in [Role, Tenant];
entity Service in [Role, Tenant];
entity System;
entity Tool = {
  name: String,
  provider: String,
  object: String,
  verb: String,
  sideEffect: String
};
entity MemoryScope;

// Each compiled policy set declares the tool-input fields its conditions reference.
type ToolInput = {INPUT_FIELDS};
type ToolContext = { tainted: Bool, approved: Bool, input: ToolInput };
type BaseContext = { tainted: Bool, approved: Bool };

action "tool.invoke" appliesTo {
  principal: [Agent, User, App, Service, System],
  resource: [Tool],
  context: ToolContext
};
action "memory.read", "memory.write" appliesTo {
  principal: [Agent, User, App, Service, System],
  resource: [MemoryScope],
  context: BaseContext
};
action {WORKLOAD_ACTIONS} appliesTo {
  principal: [Agent],
  resource: [Tenant],
  context: BaseContext
};
action {CONTROL_ACTIONS} appliesTo {
  principal: [User, Service],
  resource: [Tenant],
  context: BaseContext
};
"""

InputType = Literal["decimal", "String", "Bool"]


def _names(actions: frozenset[PolicyAction]) -> str:
    return ", ".join(f'"{action.value}"' for action in sorted(actions))


def schema_text(input_fields: Mapping[str, InputType] | None = None) -> str:
    """The Cedar schema, with the tool-input fields that the policies reference."""
    fields = ", ".join(f"{name}?: {kind}" for name, kind in sorted((input_fields or {}).items()))
    return (
        SCHEMA_TEMPLATE.replace("{INPUT_FIELDS}", f"{{ {fields} }}" if fields else "{}")
        .replace("{WORKLOAD_ACTIONS}", _names(WORKLOAD_ACTIONS))
        .replace("{CONTROL_ACTIONS}", _names(CONTROL_ACTIONS))
    )
